ALTER TABLE response_jobs ADD COLUMN retired_at INTEGER;
ALTER TABLE assets ADD COLUMN storage_key TEXT;
ALTER TABLE assets ADD COLUMN storage_state TEXT NOT NULL DEFAULT 'active';
CREATE TABLE media_gc(owner TEXT NOT NULL,asset_id TEXT NOT NULL,PRIMARY KEY(owner,asset_id));
CREATE TABLE work_quotes(approval_id TEXT PRIMARY KEY,owner TEXT NOT NULL,quote_hash TEXT NOT NULL,snapshot_json TEXT NOT NULL,confirmation_text TEXT NOT NULL,user_confirmation TEXT,confirmed_at INTEGER);
CREATE INDEX response_history ON response_jobs(owner,retired_at,created_at);
CREATE TRIGGER protect_response_jobs_input_asset_insert BEFORE INSERT ON response_jobs WHEN NEW.input_asset IS NOT NULL AND EXISTS(SELECT 1 FROM assets WHERE id=NEW.input_asset AND owner=NEW.owner AND storage_state!='active') BEGIN SELECT RAISE(ABORT,'Referenced file is not available'); END;
CREATE TRIGGER protect_response_jobs_input_asset_update BEFORE UPDATE ON response_jobs WHEN NEW.input_asset IS NOT NULL AND EXISTS(SELECT 1 FROM assets WHERE id=NEW.input_asset AND owner=NEW.owner AND storage_state!='active') BEGIN SELECT RAISE(ABORT,'Referenced file is not available'); END;
